@import url\('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Poppins:wght@600;700;800&display=swap'\);

@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  margin: 0;
  font-family: 'DM Sans', 'Plus Jakarta Sans', 'Inter', system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-color: #f9fafb;
  color: #1f2937;
}

/* ── Standardized Buttons \(Duolingo style\) ── */
.btn-primary {
  background-color: #22c55e;
  color: #ffffff;
  font-weight: 900;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  border: none;
  transition: all 150ms ease;
  user-select: none;
  cursor: pointer;
  display: inline-block;
  text-align: center;
  font-size: 1rem;
}
.btn-primary:hover {
  background-color: #16a34a;
}
.btn-primary:active {
  transform: translateY\(0\) scale\(0.98\);
}
.btn-primary:disabled { 
  opacity: 0.5; 
  cursor: not-allowed; 
  transform: none; 
}

.btn-secondary {
  background-color: #ffffff;
  color: #1e1b4b;
  font-weight: 900;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  border: 2px solid #d1d5db;
  transition: all 150ms ease;
  user-select: none;
  cursor: pointer;
  display: inline-block;
  text-align: center;
}
.btn-secondary:hover {
  border-color: #22c55e;
}
.btn-secondary:active { 
  transform: translateY\(0\); 
}

.btn-danger {
  background-color: #ef4444;
  color: #ffffff;
  font-weight: 900;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  border: none;
  transition: all 150ms ease;
  user-select: none;
  cursor: pointer;
  display: inline-block;
  text-align: center;
}
.btn-danger:hover {
  background-color: #dc2626;
}
.btn-danger:active { 
  transform: translateY\(0\); 
}

.btn-accent {
  background-color: #06b6d4;
  color: #ffffff;
  font-weight: 900;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  border: none;
  transition: all 150ms ease;
  user-select: none;
  cursor: pointer;
  display: inline-block;
  text-align: center;
}
.btn-accent:hover {
  background-color: #0891b2;
}
.btn-accent:active { 
  transform: translateY\(0\); 
}

/* ── Standardized Card ── */
.card {
  background-color: #ffffff;
  border-radius: 0.5rem;
  border: 1px solid #e5e7eb;
  box-shadow: 0 1px 2px 0 rgba\(0, 0, 0, 0.05\);
}

/* ── Standardized Input ── */
.input-field {
  width: 100%;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  border: 1px solid #d1d5db;
  background-color: #ffffff;
  color: #1e1b4b;
  font-weight: 600;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.2s;
  box-sizing: border-box;
}
.input-field::placeholder { 
  color: #94a3b8; 
}
.input-field:focus {
  border-color: #22c55e;
  outline: none;
}

/* Override browser autofill styles */
.input-field:-webkit-autofill,
.input-field:-webkit-autofill:hover,
.input-field:-webkit-autofill:focus {
  -webkit-text-fill-color: #1f2937;
  -webkit-box-shadow: 0 0 0 1000px #ffffff inset;
  border-color: #22c55e;
  transition: background-color 5000s ease-in-out 0s;
}

/* ── Progress bar ── */
.progress-bar {
  height: 0.625rem;
  background-color: #e5e7eb;
  border-radius: 9999px;
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background-color: #22c55e;
  border-radius: 9999px;
  transition: all 500ms ease-out;
}

/* ── Scroll reveal animations ── */
.reveal {
  opacity: 0;
  transform: translateY\(32px\);
  transition: opacity 0.7s cubic-bezier\(0.16, 1, 0.3, 1\),
              transform 0.7s cubic-bezier\(0.16, 1, 0.3, 1\);
}
.reveal.visible { 
  opacity: 1; 
  transform: translateY\(0\); 
}

.reveal-left {
  opacity: 0;
  transform: translateX\(-48px\);
  transition: opacity 0.7s cubic-bezier\(0.16, 1, 0.3, 1\),
              transform 0.7s cubic-bezier\(0.16, 1, 0.3, 1\);
}
.reveal-left.visible { 
  opacity: 1; 
  transform: translateX\(0\); 
}

.reveal-right {
  opacity: 0;
  transform: translateX\(48px\);
  transition: opacity 0.7s cubic-bezier\(0.16, 1, 0.3, 1\),
              transform 0.7s cubic-bezier\(0.16, 1, 0.3, 1\);
}
.reveal-right.visible { 
  opacity: 1; 
  transform: translateX\(0\); 
}

.reveal-scale {
  opacity: 0;
  transform: scale\(0.92\);
  transition: opacity 0.6s cubic-bezier\(0.16, 1, 0.3, 1\),
              transform 0.6s cubic-bezier\(0.16, 1, 0.3, 1\);
}
.reveal-scale.visible { 
  opacity: 1; 
  transform: scale\(1\); 
}

/* ── Floating animation ── */
@keyframes float {
  0%, 100% { transform: translateY\(0\); }
  50% { transform: translateY\(-12px\); }
}
.float-animation { 
  animation: float 4s ease-in-out infinite; 
}
.float-animation-delayed { 
  animation: float 4s ease-in-out 1s infinite; 
}
.float-animation-slow { 
  animation: float 5s ease-in-out 0.5s infinite; 
}

/* ── Mobile menu overlay ── */
.mobile-menu-overlay {
  background-color: rgba\(0, 0, 0, 0.25\);
  backdrop-filter: blur\(4px\);
}

/* ── Demo animations ── */

/* Advanced option reveal with spring physics */
@keyframes optionReveal {
  0% {
    opacity: 0;
    transform: translateY\(24px\) scale\(0.95\);
    filter: blur\(4px\);
  }
  70% {
    transform: translateY\(-4px\) scale\(1.02\);
  }
  100% {
    opacity: 1;
    transform: translateY\(0\) scale\(1\);
    filter: blur\(0\);
  }
}

/* Glow effect for selected answer */
@keyframes optionGlow {
  0% {
    box-shadow: 0 0 0 0 rgba\(99, 102, 241, 0.7\);
  }
  70% {
    box-shadow: 0 0 0 10px rgba\(99, 102, 241, 0\);
  }
  100% {
    box-shadow: 0 0 20px 0 rgba\(99, 102, 241, 0.4\), inset 0 0 20px -5px rgba\(99, 102, 241, 0.3\);
  }
}

/* Premium badge pop with spring */
@keyframes premiumPop {
  0% {
    transform: scale\(0\) rotate\(-15deg\);
    opacity: 0;
  }
  50% {
    transform: scale\(1.15\) rotate\(5deg\);
  }
  85% {
    transform: scale\(0.95\) rotate\(-2deg\);
  }
  100% {
    transform: scale\(1\) rotate\(0\);
    opacity: 1;
  }
}

/* Checkmark pulse */
@keyframes checkPulse {
  0% {
    transform: scale\(0\) rotate\(-45deg\);
    opacity: 0;
  }
  50% {
    transform: scale\(1.2\) rotate\(10deg\);
  }
  100% {
    transform: scale\(1\) rotate\(0\);
    opacity: 1;
  }
}

.demo-option {
  animation: optionReveal 0.5s cubic-bezier\(0.34, 1.56, 0.64, 1\) forwards;
  animation-delay: var\(--delay, 0\);
  transition: all 0.3s cubic-bezier\(0.16, 1, 0.3, 1\);
}

.demo-option:hover {
  transform: translateY\(-2px\);
}

.demo-correct {
  animation: optionGlow 0.8s cubic-bezier\(0.34, 1.56, 0.64, 1\) forwards;
}

.demo-correct .checkmark-icon {
  animation: checkPulse 0.6s cubic-bezier\(0.34, 1.56, 0.64, 1\);
}

.demo-badge {
  animation: premiumPop 0.6s cubic-bezier\(0.34, 1.56, 0.64, 1\) forwards;
}

/* ── Gamification Animations ── */

/* Squash and stretch button animation */
@keyframes squash-stretch {
  0%, 100% { transform: scale\(1, 1\); }
  25% { transform: scale\(1.1, 0.9\); }
  75% { transform: scale\(0.9, 1.1\); }
}

/* Success celebration pop */
@keyframes celebrate {
  0% { transform: scale\(0\) rotate\(-45deg\); opacity: 0; }
  50% { transform: scale\(1.2\) rotate\(10deg\); }
  100% { transform: scale\(1\) rotate\(0\); opacity: 1; }
}

/* Confetti fall animation */
@keyframes confetti-fall {
  0% { transform: translateY\(-100px\) rotate\(0deg\); opacity: 1; }
  100% { transform: translateY\(100vh\) rotate\(720deg\); opacity: 0; }
}

/* Level up glow */
@keyframes level-up-glow {
  0% { transform: scale\(1\); box-shadow: 0 0 0 0 rgba\(34, 197, 94, 0.7\); }
  50% { transform: scale\(1.1\); box-shadow: 0 0 0 20px rgba\(34, 197, 94, 0\); }
  100% { transform: scale\(1\); box-shadow: 0 0 0 0 rgba\(34, 197, 94, 0\); }
}

/* XP pop float */
@keyframes xp-pop {
  0% { transform: translateY\(0\) scale\(1\); opacity: 1; }
  100% { transform: translateY\(-50px\) scale\(1.5\); opacity: 0; }
}

/* Unlock badge animation */
@keyframes unlock-badge {
  0% { transform: rotateX\(-90deg\) rotateY\(0deg\); opacity: 0; }
  50% { transform: rotateX\(10deg\) rotateY\(10deg\); }
  100% { transform: rotateX\(0deg\) rotateY\(0deg\); opacity: 1; }
}

/* Streak flame flicker */
@keyframes flame-flicker {
  0%, 100% { transform: scaleY\(1\) rotate\(0deg\); }
  25% { transform: scaleY\(1.1\) rotate\(1deg\); }
  50% { transform: scaleY\(0.95\) rotate\(-2deg\); }
  75% { transform: scaleY\(1.05\) rotate\(1deg\); }
}

.celebrate { animation: celebrate 0.6s cubic-bezier\(0.34, 1.56, 0.64, 1\); }
.level-up { animation: level-up-glow 0.8s ease-out; }
.xp-pop { animation: xp-pop 1s ease-out forwards; }
.unlock-badge { animation: unlock-badge 0.8s cubic-bezier\(0.34, 1.56, 0.64, 1\); }
.flame-flicker { animation: flame-flicker 2s ease-in-out infinite; }
.confetti-particle { animation: confetti-fall 3s ease-out forwards; }

/* ── RTL Support \(Arabic\) ── */
[dir="rtl"] {
  text-align: right;
  direction: rtl;
}

[dir="rtl"] .card {
  direction: rtl;
}

[dir="rtl"] .input-field {
  text-align: right;
}

[dir="rtl"] .flex {
  flex-direction: row-reverse;
}

[dir="rtl"] .gap-3 {
  gap: 0.75rem;
}

[dir="rtl"] .gap-4 {
  gap: 1rem;
}

[dir="rtl"] .pr-4 {
  padding-right: 0;
  padding-left: 1rem;
}

[dir="rtl"] .pl-4 {
  padding-left: 0;
  padding-right: 1rem;
}

[dir="rtl"] .space-y-3 > * + * {
  margin-top: 0.75rem;
}

[dir="rtl"] .space-y-4 > * + * {
  margin-top: 1rem;
}

/* RTL specific animations */
[dir="rtl"] .reveal-left {
  transform: translateX\(48px\);
}

[dir="rtl"] .reveal-left.visible {
  transform: translateX\(0\);
}

[dir="rtl"] .reveal-right {
  transform: translateX\(-48px\);
}

[dir="rtl"] .reveal-right.visible {
  transform: translateX\(0\);
}
EOF)

